async function loadLookbookPresentation(db: Awaited<ReturnType<typeof getDb>>, lookbook: typeof lookbooks.$inferSelect) {
  if (!db) return { ...lookbook, presentation: null };
  const queryResults = await Promise.all([
    db.select().from(stories).where(eq(stories.projectId, lookbook.projectId)).orderBy(desc(stories.createdAt)).limit(1),
    db.select().from(blueprints).where(eq(blueprints.projectId, lookbook.projectId)).orderBy(desc(blueprints.createdAt)).limit(1),
    db.select().from(floralSelections).where(and(eq(floralSelections.projectId, lookbook.projectId), eq(floralSelections.decision, "accepted"))).orderBy(desc(floralSelections.createdAt)).limit(100),
    db.select().from(renderAssets).where(and(eq(renderAssets.projectId, lookbook.projectId), eq(renderAssets.status, "approved"))).orderBy(desc(renderAssets.createdAt)).limit(100),
  ]);
  const storyRows = (queryResults[0] ?? []) as Array<typeof stories.$inferSelect>;
  const blueprintRows = (queryResults[1] ?? []) as Array<typeof blueprints.$inferSelect>;
  const decisionRows = (queryResults[2] ?? []) as Array<typeof floralSelections.$inferSelect>;
  const assetRows = (queryResults[3] ?? []) as Array<typeof renderAssets.$inferSelect>;
  return { ...lookbook, presentation: { story: storyRows[0] ?? null, blueprint: blueprintRows[0] ?? null, acceptedFlorals: decisionRows, approvedAssets: assetRows } };
}

